<?php
declare(strict_types=1);

function event_day_label(string $date): string { return (new DateTimeImmutable($date))->format('d/m/Y'); }
function event_time_label(array $event): string { return $event['starts_at'] === null ? 'Dia inteiro' : substr($event['starts_at'], 0, 5) . ' – ' . substr($event['ends_at'], 0, 5); }
function event_badge(array $event): string { return '<span class="agenda-badges">' . recurrence_badge($event) . '<span class="event-priority priority-' . e($event['priority']) . '">' . e(event_priorities()[$event['priority']]) . '</span></span>'; }
function render_notification_item(array $event): void { ?>
<?php $isTask = ($event['item_kind'] ?? 'event') === 'task'; $isInvite = ($event['item_kind'] ?? '') === 'invitation'; ?>
<article class="notification-item <?= $event['read_at'] === null ? 'unread' : '' ?>" data-notification-id="<?= (int) $event['notification_id'] ?>" data-notification-kind="<?= $isInvite ? 'invitation' : ($isTask ? 'task' : 'event') ?>">
<div><a href="<?= e(url($isInvite ? 'view-invitation' : ($isTask ? 'view-task' : 'view-event'), ['id' => $event['id']])) ?>"><strong><?= $isInvite ? 'Convite: ' : ($isTask ? 'Tarefa: ' : '') ?><?= e($event['title']) ?></strong></a><p><?= e(event_day_label($event['event_date'])) ?> · <?= e(event_time_label($event)) ?></p><?= event_badge($event) ?><?php if ($isInvite): ?><small class="event-subject"><?= e(invitation_states()[$event['invitation_state']]) ?></small><?php endif; ?><small class="event-subject"><?= e(event_category_label($event)) ?></small><?php if ($event['subject_name'] !== null): ?><small class="event-subject"><?= e($event['subject_name']) ?></small><?php endif; ?></div>
<?php if ($event['read_at'] === null): ?><form method="post" action="<?= e(url($isInvite ? 'read-invitation' : ($isTask ? 'read-task-notification' : 'read-notification'))) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $event['notification_id'] ?>"><button class="plain-button" aria-label="Marcar <?= e($event['title']) ?> como lida" title="Marcar como lida"><?= icon('check') ?></button></form><?php else: ?><small>Lida</small><?php endif; ?></article>
<?php }
function render_notification_menu(int $userId): void {
    $count = notification_count($userId, true); ?>
<details class="notification-menu" data-notification-menu><summary class="icon-button" aria-label="Notificações<?= $count ? ': ' . $count . ' não lidas' : '' ?>" title="Notificações"><?= icon('bell') ?><?php if ($count): ?><span class="notification-count"><?= $count > 99 ? '99+' : $count ?></span><?php endif; ?></summary><div class="notification-popover"><div class="notification-heading"><strong>Notificações</strong><a href="<?= e(url('notifications')) ?>">Ver todas</a></div><?php foreach (event_notifications($userId, true, 5) as $event): render_notification_item($event); endforeach; ?><?php if (!$count): ?><p class="notification-empty">Nenhum aviso pendente.</p><?php endif; ?><p class="notification-footnote">Convites para aceitar ou recusar. Avisos de eventos e tarefas no dia marcado ou no próximo acesso.</p></div></details>
<?php }
function render_agenda(array $user): void {
    $today = date('Y-m-d');
    $month = $_GET['mes'] ?? substr($today, 0, 7);
    if (!is_string($month) || !preg_match('/^[1-9][0-9]{3}-(?:0[1-9]|1[0-2])$/D', $month)) { fail('Selecione um mês válido.'); }
    $first = new DateTimeImmutable($month . '-01');
    $selected = event_date($_GET['dia'] ?? ($month === substr($today, 0, 7) ? $today : $first->format('Y-m-d')));
    if (substr($selected, 0, 7) !== $month) { fail('Selecione um dia deste mês.'); }
    $begin = $first->modify('-' . $first->format('w') . ' days');
    $last = $begin->modify('+41 days');
    $events = query('SELECT e.*, s.name AS subject_name FROM hc_portal_events e LEFT JOIN hc_portal_subjects s ON s.id = e.subject_id WHERE e.user_id = ? AND e.event_date BETWEEN ? AND ? ORDER BY e.event_date, CASE e.priority WHEN \'urgente\' THEN 0 WHEN \'media\' THEN 1 ELSE 2 END, e.starts_at, e.title, e.id', [$user['id'], $begin->format('Y-m-d'), $last->format('Y-m-d')])->fetchAll();
    foreach ($events as &$event) { $event['item_kind'] = 'event'; } unset($event);
    foreach (task_list((int) $user['id'], null, $begin->format('Y-m-d'), $last->format('Y-m-d')) as $task) { $task['item_kind'] = 'task'; $events[] = $task; }
    usort($events, function ($a, $b) { $rank = ['urgente' => 0, 'media' => 1, 'baixa' => 2]; return [$a['event_date'], $rank[$a['priority']], $a['starts_at'] ?? '', $a['title'], $a['id'], $a['item_kind']] <=> [$b['event_date'], $rank[$b['priority']], $b['starts_at'] ?? '', $b['title'], $b['id'], $b['item_kind']]; });
    $days = []; foreach ($events as $event) { $days[$event['event_date']][] = $event; }
    $months = [1 => 'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
    page_start('Agenda', 'agenda'); ?>
<div class="page-heading"><div><span class="eyebrow">SEU TEMPO, ORGANIZADO</span><h1>Minha agenda</h1><p>Planeje seus compromissos e estudos. Só você vê seus eventos e tarefas.</p></div><div class="heading-actions"><a class="button button-primary" href="<?= e(url('new-task', ['dia' => $selected])) ?>"><?= icon('check') ?>Nova tarefa</a><a class="button button-primary" href="<?= e(url('new-event', ['dia' => $selected])) ?>"><?= icon('plus') ?>Novo evento</a></div></div>
<section class="agenda-card" aria-label="Calendário mensal"><div class="calendar-toolbar"><h2><?= e($months[(int) $first->format('n')] . ' ' . $first->format('Y')) ?></h2><nav class="calendar-month-nav" aria-label="Navegar pelos meses"><?php if ($month > '1000-01'): ?><a class="icon-button" href="<?= e(url('agenda', ['mes' => $first->modify('-1 month')->format('Y-m')])) ?>" aria-label="Mês anterior"><?= icon('back') ?></a><?php endif; ?><?php if ($month < '9999-12'): ?><a class="icon-button" href="<?= e(url('agenda', ['mes' => $first->modify('+1 month')->format('Y-m')])) ?>" aria-label="Próximo mês"><?= icon('arrow') ?></a><?php endif; ?></nav></div>
<div class="calendar-weekdays" aria-hidden="true"><?php foreach (['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'] as $day): ?><span><?= $day ?></span><?php endforeach; ?></div><div class="calendar-grid">
<?php for ($i = 0; $i < 42; $i++): $day = $begin->modify('+' . $i . ' days'); $date = $day->format('Y-m-d'); $valid = (int) $day->format('Y') >= 1000 && (int) $day->format('Y') <= 9999; $dayEvents = $days[$date] ?? []; ?>
<div class="calendar-day <?= $day->format('Y-m') !== $month ? 'outside-month' : '' ?> <?= $date === $today ? 'is-today' : '' ?> <?= $date === $selected ? 'is-selected' : '' ?>" data-calendar-day="<?= e($date) ?>">
<?php if ($valid): ?><a class="calendar-date" href="<?= e(url('agenda', ['mes' => $day->format('Y-m'), 'dia' => $date])) ?>" aria-label="<?= e(event_day_label($date)) ?>, <?= count($dayEvents) ?> itens" <?= $date === $selected ? 'aria-current="date"' : '' ?>><?= $day->format('j') ?><span class="calendar-event-count"><?= count($dayEvents) ?: '' ?></span></a><?php endif; ?>
<div class="calendar-events"><?php foreach (array_slice($dayEvents, 0, 3) as $event): ?><a class="calendar-event priority-<?= e($event['priority']) ?>" href="<?= e(url($event['item_kind'] === 'task' ? 'view-task' : 'view-event', ['id' => $event['id']])) ?>" title="<?= e((!empty($event['recurrence_id']) ? 'Recorrente · ' : '') . event_priorities()[$event['priority']] . ' · ' . event_time_label($event) . ' · ' . $event['title']) ?>"><?= !empty($event['recurrence_id']) ? '↻ ' : '' ?><?= $event['item_kind'] === 'task' ? (!empty($event['completed_at']) ? '✓ ' : '☐ ') : '' ?><?= e($event['title']) ?></a><?php endforeach; ?><?php if (count($dayEvents) > 3): ?><small>+<?= count($dayEvents) - 3 ?> itens</small><?php endif; ?></div></div>
<?php endfor; ?></div><div class="calendar-legend"><?php foreach (event_priorities() as $key => $label): ?><span class="event-priority priority-<?= $key ?>"><?= $label ?></span><?php endforeach; ?></div></section>
<section class="agenda-day-list" aria-labelledby="selected-day-heading"><div class="calendar-toolbar"><h2 id="selected-day-heading">Eventos e tarefas de <?= e(event_day_label($selected)) ?></h2><a class="button button-primary" href="<?= e(url('new-event', ['dia' => $selected])) ?>"><?= icon('plus') ?>Adicionar neste dia</a></div>
<?php if (empty($days[$selected])): ?><div class="agenda-empty"><?= icon('calendar') ?><p>Nenhum evento ou tarefa neste dia.</p></div><?php endif; ?>
<?php foreach ($days[$selected] ?? [] as $event): if ($event['item_kind'] === 'task') { render_task_row($event, url('agenda', ['mes' => $month, 'dia' => $selected])); continue; } ?><article class="agenda-event-row" data-event-row="<?= (int) $event['id'] ?>"><div><a href="<?= e(url('view-event', ['id' => $event['id']])) ?>"><strong><?= e($event['title']) ?></strong></a><p><?= e(event_time_label($event)) ?> · <?= e(event_category_label($event)) ?><?php if ($event['subject_name'] !== null): ?> · <?= e($event['subject_name']) ?><?php endif; ?></p></div><?= event_badge($event) ?></article><?php endforeach; ?></section>
<?php page_end();
}
function render_agenda_fields(?array $event, string $date, string $kind = 'evento'): void { ?>
<label>Título<input name="title" maxlength="180" value="<?= e($event['title'] ?? '') ?>" required></label><label>Descrição<textarea name="description" maxlength="5000" rows="4"><?= e($event['description'] ?? '') ?></textarea></label>
<label>Categoria<select name="category" required><option value="">Selecione a categoria</option><?php foreach (event_categories() as $key => $label): ?><option value="<?= e($key) ?>" <?= ($event['category'] ?? '') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
<div class="event-form-grid"><label>Data<input type="date" name="event_date" min="1000-01-01" max="9999-12-31" value="<?= e($date) ?>" required></label><label>Tipo de <?= e($kind) ?><select name="all_day"><option value="1" <?= empty($event['starts_at']) ? 'selected' : '' ?>>Dia inteiro, sem horário</option><option value="0" <?= !empty($event['starts_at']) ? 'selected' : '' ?>>Com horário de início e fim</option></select></label></div>
<div class="event-form-grid" data-event-times><label>Início<input type="time" name="starts_at" value="<?= e(substr($event['starts_at'] ?? '', 0, 5)) ?>"></label><label>Fim<input type="time" name="ends_at" value="<?= e(substr($event['ends_at'] ?? '', 0, 5)) ?>"></label></div>
<div class="event-form-grid"><label>Prioridade<select name="priority" required><?php foreach (event_priorities() as $key => $label): ?><option value="<?= $key ?>" <?= ($event['priority'] ?? 'media') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Matéria<select name="subject_id"><option value="">Sem matéria</option><?php foreach (subject_list() as $subject): ?><option value="<?= (int) $subject['id'] ?>" <?= (int) ($event['subject_id'] ?? 0) === (int) $subject['id'] ? 'selected' : '' ?>><?= e($subject['name']) ?></option><?php endforeach; ?></select></label></div>
<?php }
function render_event_form(?array $event): void {
    $date = $event ? $event['event_date'] : event_date($_GET['dia'] ?? date('Y-m-d'));
    detail_start($event ? 'Editar evento' : 'Novo evento', 'agenda', true); ?>
<a class="back-link" href="<?= e($event ? url('view-event', ['id' => $event['id']]) : url('agenda', ['mes' => substr($date, 0, 7), 'dia' => $date])) ?>"><?= icon('back') ?>Voltar</a><div class="page-heading"><div><span class="eyebrow">MINHA AGENDA</span><h1><?= $event ? 'Editar evento' : 'Novo evento' ?></h1><p>Este evento é privado e aparece apenas para você.</p></div><?php if (modal_request()): ?><div class="heading-actions"><button type="button" class="button button-primary note-edit-button" data-close title="Fechar"><?= icon('close') ?><span class="sr-only">Fechar</span></button></div><?php endif; ?></div>
<section class="form-card event-form-card"><form method="post" action="<?= e(url($event ? 'update-event' : 'create-event')) ?>" data-event-form><?= csrf() ?><?php if ($event): ?><input type="hidden" name="id" value="<?= (int) $event['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $event['revision'] ?>"><?php endif; ?>
<?php render_agenda_fields($event, $date); render_recurrence_fields($event, $date); ?>
<div class="modal-actions"><?php if (modal_request()): ?><button type="button" class="button button-secondary" data-close>Cancelar</button><?php else: ?><a class="button button-secondary" href="<?= e(url('agenda', ['mes' => substr($date, 0, 7), 'dia' => $date])) ?>">Cancelar</a><?php endif; ?><button class="button button-primary" type="submit"><?= icon('check') ?>Salvar evento</button></div></form></section>
<?php detail_end();
}
function render_event(array $event): void {
    detail_start('Evento', 'agenda', true); ?>
<a class="back-link" href="<?= e(url('agenda', ['mes' => substr($event['event_date'], 0, 7), 'dia' => $event['event_date']])) ?>"><?= icon('back') ?>Voltar à agenda</a><div class="page-heading"><div><span class="eyebrow">MINHA AGENDA</span><h1><?= e($event['title']) ?></h1><p><?= e(event_day_label($event['event_date'])) ?> · <?= e(event_time_label($event)) ?></p></div><div class="heading-actions"><a class="button button-secondary" href="<?= e(url('edit-event', ['id' => $event['id']])) ?>"><?= icon('edit') ?>Editar</a><button type="button" class="icon-button" data-open="delete-event-dialog" aria-label="Excluir evento"><?= icon('trash') ?></button><?php if (modal_request()): ?><button type="button" class="button button-primary note-edit-button" data-close title="Fechar"><?= icon('close') ?><span class="sr-only">Fechar</span></button><?php endif; ?></div></div>
<section class="form-card event-detail"><?= event_badge($event) ?><p>Categoria: <?= e(event_category_label($event)) ?></p><p>Matéria: <?php if ($event['subject_name'] !== null): ?><a href="<?= e(subject_url($event['subject_id'])) ?>"><?= e($event['subject_name']) ?></a><?php else: ?>Sem matéria<?php endif; ?></p><?php if ($event['description'] !== ''): ?><div class="event-description"><?= nl2br(e($event['description'])) ?></div><?php else: ?><p class="muted">Sem descrição.</p><?php endif; ?></section>
<?php render_content_section('event', $event); render_event_tasks($event); render_event_invitations($event); ?>
<dialog id="delete-event-dialog" class="modal"><div class="modal-heading"><h2>Excluir evento</h2><button class="icon-button" data-close aria-label="Fechar"><?= icon('close') ?></button></div><p>Excluir “<?= e($event['title']) ?>” e seu aviso? As tarefas vinculadas serão preservadas como avulsas. Esta ação não pode ser desfeita.</p><form method="post" action="<?= e(url('delete-event')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $event['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $event['revision'] ?>"><?php render_recurrence_delete_scope($event); ?><label class="confirmation-check"><input type="checkbox" name="confirm" value="1" required>Confirmo a exclusão deste evento.</label><div class="modal-actions"><button class="button button-secondary" type="button" data-close>Cancelar</button><button class="button button-danger" type="submit">Excluir evento</button></div></form></dialog>
<?php detail_end();
}
function render_notifications(array $user): void {
    sync_event_notifications((int) $user['id']);
    $total = notification_count((int) $user['id']);
    $pages = max(1, (int) ceil($total / 20));
    $page = min($pages, max(1, numeric_id($_GET['pagina'] ?? 1)));
    page_start('Notificações', 'agenda'); ?>
<div class="page-heading"><div><span class="eyebrow">MINHA AGENDA</span><h1>Notificações</h1><p>Seus avisos ficam pendentes até você marcá-los como lidos.</p></div><a class="button button-secondary" href="<?= e(url('agenda')) ?>">Abrir agenda</a></div><section class="agenda-card notification-list"><?php foreach (event_notifications((int) $user['id'], false, 20, ($page - 1) * 20) as $event): render_notification_item($event); endforeach; ?><?php if (!$total): ?><p class="notification-empty">Você ainda não tem notificações.</p><?php endif; ?></section>
<?php if ($pages > 1): ?><nav class="calendar-toolbar" aria-label="Paginação de notificações"><?php if ($page > 1): ?><a href="<?= e(url('notifications', ['pagina' => $page - 1])) ?>">Anterior</a><?php endif; ?><span>Página <?= $page ?> de <?= $pages ?></span><?php if ($page < $pages): ?><a href="<?= e(url('notifications', ['pagina' => $page + 1])) ?>">Próxima</a><?php endif; ?></nav><?php endif; page_end();
}
